import { loadFont as loadInterTight } from "@remotion/google-fonts/InterTight";
import React, { forwardRef, useEffect, useId, useImperativeHandle, useLayoutEffect, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Chrome parks a glyph raster on a whole pixel vertically for as long as the
// matrix that carries it is axis-aligned, so text under a slow transform
// clicks along pixel by pixel. A lean too small to see takes it off that grid.
//
// A transform that carries text is marked, and told when it moves:
//
//   const glide = useGlide();
//   transform: `scale(${s})${glide(moving)}`
//
// The mark changes nothing by itself. After every frame the blocks of text
// under a marked transform get the lean: each about its own centre, and each
// by no more than its size on the screen needs. A card, a hairline or an image
// is fine under a transform as it is, so they stay level.
//
// Text leans while its transform moves, and it keeps the lean at rest when it
// rests off the pixel grid (a scene shown smaller in a player, a camera that
// holds at 1.03): dropping the lean there would snap it to the nearest pixel,
// up to half a pixel in one frame, and picking it up would snap it back. Text
// that rests on the grid loses the lean without moving, so a scene at rest at
// full size is drawn exactly as it would be without any of this.

/**
 * Returns `glide(moving)`: append it to a transform that carries text, with
 * `moving` true on the frames where that transform changes.
 *
 * Everything else lives inside this one closure: the build of Studio
 * elements pastes this file whole into the component that uses it, where a
 * second `LEAN` or `lean` at the top level would collide.
 */
const useGlide = (() => {
  /** What `glide(false)` adds to a transform: an identity matrix, to find it by. */
  const AT_REST = " matrix(1, 0, 0, 1, 0, 0)";
  /** `glide(true)` adds it twice. */
  const MOVING = AT_REST + AT_REST;
  const MARKED = `[style*="${AT_REST.trim()}"]`;
  // Text leaves the grid once the matrix leans x into y by half of 1/1024 in
  // device pixels (Skia rounds the glyph matrix to 1/1024). A fifth over it.
  const LEAN = 0.6 / 1024;
  // Past this the text is a speck on the screen; it is left alone.
  const STEEPEST = 5;
  // How far from a whole pixel text may rest and still count as on the grid:
  // the jump it makes when the lean goes is no bigger than this.
  const ON_GRID = 0.05;

  /** The linear part of a 2D matrix: x' = a·x + c·y, y' = b·x + d·y. */
  type Lin = [a: number, b: number, c: number, d: number];
  const LEVEL: Lin = [1, 0, 0, 1];
  const times = (m: Lin, n: Lin): Lin => [
    m[0] * n[0] + m[2] * n[1],
    m[1] * n[0] + m[3] * n[1],
    m[0] * n[2] + m[2] * n[3],
    m[1] * n[2] + m[3] * n[3],
  ];
  const turned = (degrees: number): Lin => {
    const t = (degrees * Math.PI) / 180;
    return [Math.cos(t), Math.sin(t), -Math.sin(t), Math.cos(t)];
  };
  const offWhole = (n: number) => Math.abs(n - Math.round(n));

  type Block = HTMLElement | SVGTextElement | SVGSVGElement;
  let leant: Block[] = [];
  // Fonts arrive after the first pass and change what is laid out where, with
  // no render to follow: a block or a marked element that changes size is read
  // again before the frame is painted.
  let watcher: ResizeObserver | undefined;
  const watched = new WeakSet<Element>();
  const watch = (el: Element) => {
    if (watched.has(el)) return;
    watched.add(el);
    watcher ??= new ResizeObserver(() => lean());
    watcher.observe(el);
  };

  const depthOf = (el: Element) => {
    let depth = 0;
    for (let up = el.parentElement; up; up = up.parentElement) depth += 1;
    return depth;
  };

  /** The nearest box around a text node that a transform applies to. */
  const blockOf = (node: Node): Block | null => {
    for (let el = node.parentElement; el; el = el.parentElement) {
      if (el instanceof SVGElement) {
        const text = el.closest("text");
        if (!(text instanceof SVGTextElement)) return null;
        // Text that only shapes a mask or a clip is not drawn where it stands
        // and cannot turn by itself: its whole drawing leans for it.
        if (!text.closest("defs, mask, clipPath, pattern, symbol, marker"))
          return text;
        let drawing = text.ownerSVGElement;
        while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
        return drawing;
      }
      if (!(el instanceof HTMLElement)) continue;
      const { display } = getComputedStyle(el);
      if (display !== "inline" && display !== "contents") return el;
    }
    return null;
  };

  /** One pass over the page: what every element's own transforms do. */
  function reader(given: Map<Element, number>) {
    type Own = {
      /** `scale` and `transform`, without the `rotate` property. */
      lin: Lin;
      /** `rotate`, in degrees: a lean given in this pass, or the scene's own. */
      turn: number;
      /** How far down it is moved, and by what whole factor it is scaled from
       * its top left corner; null when it does anything else. */
      carry: { dy: number; k: number } | null;
    };
    const lens = new Map<Element, boolean>();
    /** Whether an element shows its children in perspective. */
    const lensOn = (el: Element | null): boolean => {
      if (!el) return false;
      const seen = lens.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const result =
        style.perspective !== "none" ||
        (style.transformStyle === "preserve-3d" && lensOn(el.parentElement));
      lens.set(el, result);
      return result;
    };
    const own = new Map<Element, Own | null>();
    const ownOf = (el: Element): Own | null => {
      const seen = own.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const m = new DOMMatrixReadOnly(
        style.transform === "none" ? "" : style.transform,
      );
      const scale = style.scale === "none" ? [] : style.scale.split(" ");
      const sx = scale.length ? Number.parseFloat(scale[0]) : 1;
      const sy = scale.length > 1 ? Number.parseFloat(scale[1]) : sx;
      const rotate = style.rotate === "none" ? [] : style.rotate.split(" ");
      let result: Own | null = null;
      // Seen in perspective, text is drawn on a layer of its own: not ours. A
      // turn out of the plane without perspective lands flat on the screen,
      // and text under it snaps like any other.
      // A push along z alone, or a half turn, leaves it flat even under a lens.
      const inPerspective =
        Math.max(Math.abs(m.m14), Math.abs(m.m24), Math.abs(m.m34)) > 1e-9 ||
        (Math.max(
          Math.abs(m.m13),
          Math.abs(m.m31),
          Math.abs(m.m23),
          Math.abs(m.m32),
        ) > 1e-6 &&
          lensOn(el.parentElement));
      if (!inPerspective && rotate.length < 2) {
        // The `scale` property acts on what `transform` has produced.
        const lin: Lin = [m.a * sx, m.b * sy, m.c * sx, m.d * sy];
        const moved =
          style.translate === "none"
            ? 0
            : (style.translate.split(" ")[1] ?? "0px");
        const k = Math.round(lin[0]);
        const whole =
          m.is2D &&
          k >= 1 &&
          Math.abs(lin[0] - k) < 1e-4 &&
          Math.abs(lin[3] - k) < 1e-4 &&
          Math.abs(lin[1]) < 1e-5 &&
          Math.abs(lin[2]) < 1e-5 &&
          rotate.length === 0 &&
          (moved === 0 || moved.endsWith("px")) &&
          // Scaled about its corner, a box stays where layout put it.
          (k === 1 || /^0(px)? 0(px)?/.test(style.transformOrigin));
        result = {
          lin,
          turn: rotate.length ? Number.parseFloat(rotate[0]) : 0,
          carry: whole
            ? { dy: sy * m.f + (moved === 0 ? 0 : Number.parseFloat(moved)), k }
            : null,
        };
      }
      own.set(el, result);
      return result;
    };
    const down = new Map<Element, Lin | null>();
    /** Everything from the page down to and including this element. */
    const linDown = (el: Element | null): Lin | null => {
      if (!el) return LEVEL;
      const seen = down.get(el);
      if (seen !== undefined) return seen;
      const above = linDown(el.parentElement);
      const mine = above && ownOf(el);
      const result =
        above && mine
          ? times(times(above, turned(given.get(el) ?? mine.turn)), mine.lin)
          : null;
      down.set(el, result);
      return result;
    };
    const carried = new Map<Element, { dy: number; k: number } | null>();
    const carryDown = (
      el: Element | null,
    ): { dy: number; k: number } | null => {
      if (!el) return { dy: 0, k: 1 };
      const seen = carried.get(el);
      if (seen !== undefined) return seen;
      const above = carryDown(el.parentElement);
      const mine = above && !given.has(el) ? ownOf(el)?.carry : null;
      const result =
        above && mine
          ? { dy: above.dy + above.k * mine.dy, k: above.k * mine.k }
          : null;
      carried.set(el, result);
      return result;
    };
    return { ownOf, linDown, carryDown };
  }

  /**
   * Whether text in an SVG rests on the grid: it is placed wherever it is told
   * to, so only when it is shown one to one and its baseline happens to land on
   * a whole pixel. `lands` is where its own space lands on the screen.
   */
  function restsOnGrid(text: SVGTextElement, lands: DOMMatrix | null) {
    if (!lands) return false;
    const dpr = window.devicePixelRatio;
    const style = getComputedStyle(text);
    const k = lands.d * dpr;
    const y = text.y.baseVal.numberOfItems
      ? text.y.baseVal.getItem(0).value
      : 0;
    return (
      text.y.baseVal.numberOfItems <= 1 &&
      text.dy.baseVal.numberOfItems === 0 &&
      !text.querySelector("tspan[y], tspan[dy], textPath") &&
      /^(auto|alphabetic)$/.test(style.dominantBaseline) &&
      /^(auto|baseline)$/.test(style.alignmentBaseline) &&
      Math.abs(lands.b) < 1e-6 &&
      Math.abs(lands.c) < 1e-6 &&
      Math.round(k) >= 1 &&
      offWhole(k) < 2e-3 &&
      offWhole((lands.d * y + lands.f) * dpr) < ON_GRID
    );
  }

  /**
   * The angle that takes a block off the grid, given what is above it (`above`)
   * and what its own transform does (`own`), both in device pixels: the lean is
   * a turn between the two. 0 when the block leans enough as it is, null when
   * no sane angle would do.
   */
  function angleFor(above: Lin, own: Lin): number | null {
    // y from x of `above · turn(θ) · own` is p·sin θ + q·cos θ.
    const p = above[3] * own[0] - above[1] * own[1];
    const q = above[1] * own[0] + above[3] * own[1];
    if (Math.abs(q) >= LEAN) return 0;
    if (Math.abs(p) < 1e-9) return null;
    // Along the turn the scene already has, so the two never cancel out.
    const sine = ((q < 0 ? -LEAN : LEAN) - q) / p;
    if (Math.abs(sine) > Math.sin((STEEPEST * Math.PI) / 180)) return null;
    return (Math.asin(sine) * 180) / Math.PI;
  }

  function lean() {
    for (const el of leant) {
      el.style.removeProperty("rotate");
      if (el instanceof SVGElement) el.style.removeProperty("translate");
    }
    leant = [];
    const zones = document.querySelectorAll<HTMLElement | SVGElement>(MARKED);
    if (zones.length === 0) return;
    // Each block of text under a mark, and whether any transform above it moves.
    const blocks = new Map<Block, boolean>();
    // The texts a whole drawing leans for.
    const standsFor = new Map<SVGSVGElement, SVGTextElement[]>();
    for (const zone of zones) {
      const moving = zone.style.transform.includes(MOVING.trim());
      const walker = document.createTreeWalker(zone, NodeFilter.SHOW_TEXT);
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        if (!/\S/.test(node.nodeValue ?? "")) continue;
        const block = blockOf(node);
        // A block that turns by a property of its own is left to the scene.
        if (!block || block.style.rotate) continue;
        blocks.set(block, moving || (blocks.get(block) ?? false));
        const text = node.parentElement?.closest("text");
        if (block instanceof SVGSVGElement && text instanceof SVGTextElement)
          standsFor.set(block, [...(standsFor.get(block) ?? []), text]);
      }
      watch(zone);
    }
    for (const block of blocks.keys()) watch(block);
    const dpr = window.devicePixelRatio;
    const scaled = (m: Lin): Lin => [
      m[0] * dpr,
      m[1] * dpr,
      m[2] * dpr,
      m[3] * dpr,
    ];
    // Outer blocks first: a block inside a leaning one takes only what it
    // still lacks, so leans never pile up. Everything is read before anything
    // is written; `given` stands in for the leans not yet on the page.
    const given = new Map<Element, number>();
    const { ownOf, linDown, carryDown } = reader(given);
    const writes: (() => void)[] = [];
    const ordered = [...blocks.keys()].sort((a, b) => depthOf(a) - depthOf(b));
    for (const el of ordered) {
      const moving = blocks.get(el) === true;
      if (el instanceof HTMLElement) {
        const above = linDown(el.parentElement);
        const mine = ownOf(el);
        if (!above || !mine) continue;
        if (!moving) {
          // Layout puts a baseline on a whole pixel wherever the box itself
          // sits, so text is on the grid when the transforms around it only
          // move it by whole pixels and show it one to one (or two, or three).
          const carry = carryDown(el);
          if (
            carry &&
            offWhole(carry.k * dpr) < 2e-3 &&
            offWhole(carry.dy * dpr) < ON_GRID
          )
            continue;
        }
        const angle = angleFor(scaled(above), mine.lin);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      if (el instanceof SVGSVGElement) {
        // A whole drawing: what it does itself is its own transform and the
        // scale of its viewBox, read off where it lands on the screen.
        const above = linDown(el.parentElement);
        const lands = el.getScreenCTM();
        const det = above ? above[0] * above[3] - above[1] * above[2] : 0;
        if (!above || !lands || Math.abs(det) < 1e-12) continue;
        if (
          !moving &&
          (standsFor.get(el) ?? []).every((text) =>
            restsOnGrid(text, text.getScreenCTM()),
          )
        )
          continue;
        const mine = times(
          [above[3] / det, -above[1] / det, -above[2] / det, above[0] / det],
          [lands.a, lands.b, lands.c, lands.d],
        );
        const angle = angleFor(scaled(above), mine);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      // Its drawing leans as a whole already.
      let drawing = el.ownerSVGElement;
      while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
      if (drawing && given.has(drawing)) continue;
      // Text in an SVG is placed wherever it is told to, so it is on the grid
      // only when its baseline happens to land on a whole pixel.
      const frame = el.parentNode;
      if (!(frame instanceof SVGGraphicsElement) || el.style.translate)
        continue;
      const outer = frame.getScreenCTM();
      const whole = el.getScreenCTM();
      if (
        !outer ||
        !whole ||
        Math.abs(outer.a * outer.d - outer.b * outer.c) < 1e-12
      )
        continue;
      // What the text element itself does, in the space it is placed in.
      const mine = outer.inverse().multiply(whole);
      if (!moving && restsOnGrid(el, whole)) continue;
      const angle = angleFor(scaled([outer.a, outer.b, outer.c, outer.d]), [
        mine.a,
        mine.b,
        mine.c,
        mine.d,
      ]);
      if (!angle) continue;
      // An SVG element turns about the corner of its drawing. A move brings
      // the turn to the middle of the text instead.
      const box = el.getBBox();
      const [cx, cy] = [box.x + box.width / 2, box.y + box.height / 2];
      const [px, py] = [
        mine.a * cx + mine.c * cy + mine.e,
        mine.b * cx + mine.d * cy + mine.f,
      ];
      const [cos, sin] = [turned(angle)[0], turned(angle)[1]];
      const [tx, ty] = [px - (px * cos - py * sin), py - (px * sin + py * cos)];
      writes.push(() => {
        el.style.setProperty("rotate", `${angle}deg`);
        el.style.setProperty("translate", `${tx}px ${ty}px`);
      });
      leant.push(el);
    }
    for (const write of writes) write();
  }

  const useFrameEffect =
    typeof window === "undefined" ? useEffect : useLayoutEffect;

  function useGlide() {
    // No dependencies: the lean follows whatever this frame laid out.
    useFrameEffect(lean);
    return glide;
  }

  const glide = (moving: boolean) => (moving ? MOVING : AT_REST);

  return useGlide;
})();

const inter = loadInterTight("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

interface PulseLineProps {
  text?: string;
  highlight?: string;
  caption?: string;
  beats?: number;
  /** Height of the pulse wave as it runs through the letters; 1 is the default lift. */
  amplitude?: number;
  accent?: string;
  /** Text color, as a hex value; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the line and caption. Load it yourself; Inter Tight by default. */
  fontFamily?: string;
  fontWeight?: number;
  /** Size of the line, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  grain?: boolean;
  speed?: number;
  theme?: "dark" | "light";
}

const AURORA = ["#a0f0c8", "#3fb5a3", "#5147b6", "#b25c9c"] as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    ink: "#F4F3F0",
    flat: "#9C9BA3",
    muted: "#8E8D94",
    glow: ["#F2FFF8", AURORA[0], AURORA[1]],
    hl: (accent: string) =>
      `linear-gradient(100deg, ${AURORA[0]} 0%, ${AURORA[1]} 38%, ${accent} 78%, ${AURORA[3]} 100%)`,
    ground: (k: number) =>
      `radial-gradient(70% 55% at 50% 108%, rgba(63,181,163,${(0.1 + 0.1 * k).toFixed(3)}) 0%, rgba(81,71,182,${(0.06 + 0.05 * k).toFixed(3)}) 45%, transparent 75%)`,
    grain: 0.05,
  },
  light: {
    bg: "#F5F4F0",
    ink: "#111113",
    flat: "#55545A",
    muted: "#6E6C67",
    glow: ["#0B5E52", "#1E8C7C", AURORA[2]],
    hl: (accent: string) =>
      `linear-gradient(100deg, #12806F 0%, #1E8C7C 30%, ${accent} 72%, #8C3A78 100%)`,
    ground: (k: number) =>
      `radial-gradient(70% 55% at 50% 108%, rgba(63,181,163,${(0.12 + 0.08 * k).toFixed(3)}) 0%, rgba(81,71,182,${(0.05 + 0.04 * k).toFixed(3)}) 45%, transparent 75%)`,
    grain: 0.035,
  },
} as const;

const TRACK = -0.035;
const LINE_GAP = 1.1;
const FONT_PX = 200;

const WAVE = [
  { a: 0.1, c: 1.0, w: 0.5, tent: false },
  { a: -0.09, c: 2.25, w: 0.5, tent: true },
  { a: 0.62, c: 2.9, w: 0.85, tent: true },
  { a: -0.22, c: 3.6, w: 0.6, tent: true },
  { a: 0.16, c: 5.3, w: 0.85, tent: false },
] as const;
const R_AT = 2.9;
const WAVE_LEN = 7.2;
const V = 0.42;
const FLAT_SCALE = 0.05;
const COOL = 11;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);

const midway = (p: number) => p > 0 && p < 1;
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function ecg(s: number) {
  let y = 0;
  for (const k of WAVE) {
    y += k.tent
      ? k.a * Math.max(0, 1 - Math.abs(s - k.c) / k.w)
      : k.a * Math.exp(-((s - k.c) ** 2) / (2 * k.w * k.w));
  }
  return y;
}

function mixHex(a: string, b: string, t: number) {
  const pa = Number.parseInt(a.slice(1), 16);
  const pb = Number.parseInt(b.slice(1), 16);
  const ch = (p: number, sh: number) => (p >> sh) & 255;
  const m = (sh: number) =>
    Math.round(ch(pa, sh) + (ch(pb, sh) - ch(pa, sh)) * t);
  return `rgb(${m(16)}, ${m(8)}, ${m(0)})`;
}

function heatColor(stops: readonly string[], ink: string, h: number) {
  const ramp = [ink, stops[2], stops[1], stops[0]];
  const x = Math.max(0, Math.min(1, h)) ** 1.4 * (ramp.length - 1);
  const i = Math.min(ramp.length - 2, Math.floor(x));
  return mixHex(ramp[i], ramp[i + 1], x - i);
}

interface Metrics {
  width: (s: string) => number;
  offsets: (s: string) => number[];
  caption: number;
  baseline: number;
}

function useMetrics(caption: string, family: string, weight: number) {
  const [m, setM] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("pulse-line: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      inter.waitUntilDone(),
      document.fonts.load(`${weight} 100px "${family}"`),
      document.fonts.load(`400 100px "${family}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const canvas = document.createElement("canvas");
        const ctx = canvas.getContext("2d");
        if (!ctx) throw new Error("pulse-line: no 2d context");
        ctx.font = `${weight} ${FONT_PX}px "${family}"`;
        const fm = ctx.measureText("Hg");
        const asc = fm.fontBoundingBoxAscent / FONT_PX;
        const desc = fm.fontBoundingBoxDescent / FONT_PX;
        const raw = (s: string) => ctx.measureText(s).width / FONT_PX;
        const width = (s: string) =>
          raw(s) + TRACK * Math.max(0, Array.from(s).length - 1);
        const offsets = (s: string) => {
          const chars = Array.from(s);
          return chars.map(
            (_, i) => raw(chars.slice(0, i).join("")) + TRACK * i,
          );
        };
        ctx.font = `400 ${FONT_PX}px "${family}"`;
        const cap = caption ? ctx.measureText(caption).width / FONT_PX : 0;
        setM({
          width,
          offsets,
          caption: cap,
          baseline: (1 - (asc + desc)) / 2 + asc,
        });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [caption, handle, family, weight]);
  return m;
}

function breakLines(words: string[], n: number, width: (s: string) => number) {
  if (n <= 1 || words.length <= 1) return [words.join(" ")];
  let best: string[] = [words.join(" ")];
  let bestW = Number.POSITIVE_INFINITY;
  const rec = (start: number, left: number, acc: string[]) => {
    if (left === 1) {
      const lines = [...acc, words.slice(start).join(" ")];
      const w = Math.max(...lines.map(width));
      if (w < bestW) {
        bestW = w;
        best = lines;
      }
      return;
    }
    for (let k = start + 1; k <= words.length - left + 1; k++)
      rec(k, left - 1, [...acc, words.slice(start, k).join(" ")]);
  };
  rec(0, Math.min(n, words.length), []);
  return best;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `pl${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{
        position: "absolute",
        inset: 0,
        opacity,
        mixBlendMode: "overlay",
        pointerEvents: "none",
      }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={11}
        />
        <feColorMatrix type="saturate" values="0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function PulseLineBase({
  text = "Every frame has a pulse.",
  highlight = "a pulse.",
  caption = "Motion components for Remotion. Copy one in, own every frame.",
  beats = 2,
  amplitude = 1,
  accent = "#3B5BFD",
  ink: inkProp,
  background,
  fontFamily = inter.fontFamily,
  fontWeight = 500,
  scale = 1,
  delay = 0,
  grain = true,
  speed = 1,
  theme = "dark",
}: PulseLineProps) {
  const glide = useGlide();
  const t = Math.max(0, useCurrentFrame() - delay) * speed;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const fg = inkProp ?? c.ink;
  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);
  const m = useMetrics(caption, fontFamily, fontWeight);

  const words = useMemo(() => text.split(/\s+/).filter(Boolean), [text]);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const maxW = W * 0.86;
  const capH = caption ? 0.16 : 0;
  let lines: string[] = [text];
  let F = 0;
  for (let n = 1; n <= 3; n++) {
    const ls = breakLines(words, n, m.width);
    const wEm = Math.max(...ls.map(m.width));
    const hEm = (ls.length - 1) * LINE_GAP + 1.1;
    const f = Math.min(
      maxW / wEm,
      (H * (0.7 - capH)) / hEm,
      H * (n === 1 ? 0.24 : 0.19),
    );
    if (n === 1 || f > F * 1.15) {
      lines = ls;
      F = f;
    }
    if (n === 1 && f >= H * 0.17) break;
  }

  const hlStart = highlight ? text.indexOf(highlight) : -1;
  const hlEnd = hlStart >= 0 ? hlStart + highlight.length : -1;
  type G = {
    ch: string;
    line: number;
    x: number;
    adv: number;
    strip: number;
    hl: boolean;
  };
  const glyphs: G[] = [];
  let cursor = 0;
  const lineW = lines.map(m.width);
  const blockW = Math.max(...lineW);
  for (let li = 0; li < lines.length; li++) {
    const s = lines[li];
    const offs = m.offsets(s);
    const lw = lineW[li];
    const chars = Array.from(s);
    const at = text.indexOf(s, cursor);
    const pad = (blockW - lw) / 2;
    chars.forEach((ch, i) => {
      const next = i + 1 < chars.length ? offs[i + 1] : lw + TRACK;
      const adv = next - offs[i];
      const gi = at + i;
      glyphs.push({
        ch,
        line: li,
        x: offs[i],
        adv,
        strip: pad + offs[i] + adv / 2,
        hl: gi >= hlStart && gi < hlEnd,
      });
    });
    cursor = at + s.length;
  }
  const stripLen = blockW;
  const hlBox = new Map<number, { x0: number; x1: number }>();
  for (const g of glyphs) {
    if (!g.hl || g.ch === " ") continue;
    const b = hlBox.get(g.line) ?? { x0: g.x, x1: g.x + g.adv };
    b.x0 = Math.min(b.x0, g.x);
    b.x1 = Math.max(b.x1, g.x + g.adv);
    hlBox.set(g.line, b);
  }

  const nBeats = Math.max(1, Math.min(4, Math.round(beats)));
  const run = (stripLen + WAVE_LEN + 1) / V;
  const period = Math.max(34, run + 4);
  const beatAt = (b: number) => 6 + b * period;
  const front = (b: number) => -1 + (t - beatAt(b)) * V;
  const endT = beatAt(nBeats - 1) + run;

  const blockH = (lines.length - 1) * LINE_GAP * F + F;
  const capGap = Math.max(F * 0.42, H * 0.06);
  const capSize = Math.min(
    Math.max(F * 0.17, H * 0.035),
    H * 0.044,
    (W * 0.86) / Math.max(0.1, m.caption),
  );
  const totalH = blockH + (caption ? capGap + capSize : 0);
  const top0 = (H - totalH) / 2;
  const capAt = beatAt(nBeats - 1) + run * 0.45;

  let breathe = 0;
  for (let b = 0; b < nBeats; b++) {
    const tr = beatAt(b) + (stripLen / 2 + R_AT + 1) / V;
    const d = t - tr;
    if (d > -4) breathe = Math.max(breathe, Math.exp(-((d + 0) ** 2) / 120));
  }

  const nodes: React.ReactNode[] = [];
  glyphs.forEach((g, i) => {
    if (g.ch === " ") return;
    const lw = lineW[g.line];
    const left = (W - lw * F) / 2 + g.x * F;
    const baseY = top0 + g.line * LINE_GAP * F + m.baseline * F;

    let heat = 0;
    let alive = 0;
    let hlOn = 0;
    for (let b = 0; b < nBeats; b++) {
      const s = front(b) - g.strip;
      if (s < -0.5) continue;
      const since = (s - R_AT) / V;
      if (since > -1.5) {
        heat = Math.max(
          heat,
          since < 0 ? 1 + since / 1.5 : Math.exp(-since / COOL),
        );
      }
      if (b === 0)
        alive = interpolate(s, [R_AT - 0.35, R_AT + 0.25], [0, 1], CLAMP);
      if (b === nBeats - 1 && g.hl)
        hlOn = interpolate(since, [0, 12], [0, 1], CLAMP);
    }
    const poseAt = (tt: number) => {
      let py = 0;
      let pa = 0;
      for (let b = 0; b < nBeats; b++) {
        const ps = -1 + (tt - beatAt(b)) * V - g.strip;
        if (ps < -0.5) continue;
        py += ecg(ps);
        if (b === 0)
          pa = interpolate(ps, [R_AT - 0.35, R_AT + 0.25], [0, 1], CLAMP);
      }
      const k = Math.max(0, py) / WAVE[2].a;
      return {
        dy: -py * F * (lines.length > 1 ? 0.8 : 1) * amplitude,
        sx: 1 - k * 0.06,
        sy: FLAT_SCALE + (1 - FLAT_SCALE) * pa + k * 0.22 * pa,
      };
    };
    const { dy, sx, sy } = poseAt(t);
    // The furthest glyph edge sits about F from the origin, so a scale step
    // is weighed by F to compare it with the 1e-3px used for the lift.
    const shifts = (o: ReturnType<typeof poseAt>) =>
      Math.abs(o.dy - dy) > 1e-3 ||
      Math.abs(o.sx - sx) * F > 1e-3 ||
      Math.abs(o.sy - sy) * F > 1e-3;
    const moving = shifts(poseAt(t + 1)) || shifts(poseAt(t - 1));
    // Two decimals park the glyph on a 0.01px grid; while it moves the full
    // value goes through, at rest the string is what it always was.
    const fix = (v: number, d: number) => (moving ? `${v}` : v.toFixed(d));
    const ink = alive > 0.02 ? fg : c.flat;
    const restInk = mixHex(c.flat, fg, alive);
    const col =
      heat > 0.001
        ? heatColor(c.glow, ink === fg ? fg : restInk, heat)
        : restInk;

    const style: React.CSSProperties = {
      position: "absolute",
      left,
      top: baseY - m.baseline * F,
      fontFamily,
      fontWeight,
      fontSize: F,
      lineHeight: `${F}px`,
      whiteSpace: "pre",
      transformOrigin: `${((g.adv / 2) * F).toFixed(2)}px ${(m.baseline * F).toFixed(2)}px`,
      // The tilt goes ahead of the scale: behind it, a glyph squashed to
      // `FLAT_SCALE` squashes the lean too, and the raster snaps again.
      transform: `translateY(${fix(dy, 2)}px)${glide(moving)} scale(${fix(sx, 4)}, ${fix(sy, 4)})`,
    };
    nodes.push(
      <div key={`g${i}`} style={{ ...style, color: col }}>
        {g.ch}
      </div>,
    );
    if (g.hl && hlOn > 0) {
      const box = hlBox.get(g.line);
      const bw = box ? (box.x1 - box.x0) * F : g.adv * F;
      const bx = box ? (g.x - box.x0) * F : 0;
      nodes.push(
        <div
          key={`h${i}`}
          style={{
            ...style,
            color: "transparent",
            backgroundImage: c.hl(accent),
            backgroundSize: `${bw.toFixed(2)}px 100%`,
            backgroundPosition: `${(-bx).toFixed(2)}px 0`,
            backgroundRepeat: "no-repeat",
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            opacity: hlOn * (1 - Math.min(1, heat * 0.6)),
          }}
        >
          {g.ch}
        </div>,
      );
    }
  });

  const capP = interpolate(t, [capAt, capAt + 20], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const settled = interpolate(t, [endT, endT + 30], [0, 1], CLAMP);

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {transparent ? null : (
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: c.ground(Math.max(breathe, settled * 0.35)),
          }}
        />
      )}
      <ScaleLayer scale={scale}>
        {nodes}
        {caption ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              width: W,
              top: top0 + blockH + capGap,
              textAlign: "center",
              fontFamily,
              fontWeight: 400,
              fontSize: capSize,
              letterSpacing: "-0.01em",
              lineHeight: 1.2,
              color: c.muted,
              opacity: capP,
              transform: `translateY(${midway(capP) ? (1 - capP) * capSize * 0.7 : ((1 - capP) * capSize * 0.7).toFixed(2)}px)${glide(midway(capP))}`,
            }}
          >
            {caption}
          </div>
        ) : null}
      </ScaleLayer>
      {grain ? <Grain opacity={c.grain} /> : null}
    </AbsoluteFill>
  );
}

