const ELEMENT_PROP_KEYS = new Set(["theme","accent","text","highlight","caption","beats","amplitude","fontWeight","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  text: "Every frame has a pulse.",
  highlight: "a pulse.",
  caption: "Motion components for Remotion. Copy one in, own every frame.",
  beats: 2,
  amplitude: 1,
  fontWeight: 500,
  fontFamily: "Inter Tight",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type PulseLineElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PulseLineBase>;

const PulseLineInner = forwardRef<
  HTMLDivElement,
  PulseLineElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PulseLine>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PulseLineBase
          {...(componentProps as unknown as ComponentProps<typeof PulseLineBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PulseLine = Interactive.withSchema({
  Component: PulseLineInner,
  componentName: "<PulseLine>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
